    ADD CONSTRAINT incident_actions_assigned_to_fkey FOREIGN KEY (assigned_to) REFERENCES public.profiles(id) ON DELETE SET NULL","NOTIFY pgrst, ''reload schema''"}', 'fix_incidents_fk_to_profiles');
