INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260628000001', '{"-- Migration: Add daily rate and days affected for machinery downtime cost tracking
-- Supports monetary compensation for rented machinery unavailability

-- 1. Add columns to incident_affected_items
ALTER TABLE public.incident_affected_items
  ADD COLUMN IF NOT EXISTS daily_rate NUMERIC DEFAULT 0,
  ADD COLUMN IF NOT EXISTS days_affected NUMERIC DEFAULT 0,
  ADD COLUMN IF NOT EXISTS downtime_rent_cost NUMERIC 
    GENERATED ALWAYS AS (daily_rate * days_affected) STORED","-- 2. Update trigger to include downtime_rent_cost in cost_impact
CREATE OR REPLACE FUNCTION public.calculate_incident_cost_impact()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.ended_at IS NOT NULL THEN
        NEW.cost_impact := (NEW.time_impact_hours * COALESCE(
            (SELECT SUM(hourly_cost_rate) FROM public.incident_affected_items WHERE incident_id = NEW.id),
            0
        )) + COALESCE(
            (SELECT SUM(downtime_rent_cost) FROM public.incident_affected_items WHERE incident_id = NEW.id),
            0
        );
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER","-- 3. Re-create trigger
DROP TRIGGER IF EXISTS calculate_incident_cost_impact ON public.incidents","CREATE TRIGGER calculate_incident_cost_impact
    BEFORE INSERT OR UPDATE OF ended_at ON public.incidents
    FOR EACH ROW
    EXECUTE FUNCTION public.calculate_incident_cost_impact()"}', 'add_downtime_cost_tracking');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260801000300', '{"-- Migration: Add schedule impact tracking for idempotency
-- Prevents double-applying schedule shifts via Re-apply button

ALTER TABLE public.change_order_disruptions
  ADD COLUMN IF NOT EXISTS schedule_impact_applied_at TIMESTAMPTZ","COMMENT ON COLUMN public.change_order_disruptions.schedule_impact_applied_at IS
  ''Timestamp when applyScheduleImpact was last executed. NULL if never applied. Used to prevent duplicate shifts.''"}', 'add_schedule_impact_tracking');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260628000002', '{"-- Migration: Fix cost_impact recalculation when affected items change after resolution
-- Previously cost_impact was only recalculated when ended_at changed.
-- Now it also recalculates when affected items are added, removed, or updated.

CREATE OR REPLACE FUNCTION public.recalculate_incident_cost_after_items_change()
RETURNS TRIGGER AS $$
DECLARE
    v_incident_id UUID;
BEGIN
    IF TG_OP = ''DELETE'' THEN
        v_incident_id := OLD.incident_id;
    ELSE
        v_incident_id := NEW.incident_id;
    END IF;

    UPDATE public.incidents
    SET cost_impact = (
        SELECT COALESCE(
            (SELECT SUM(hourly_cost_rate) FROM public.incident_affected_items WHERE incident_id = v_incident_id),
            0
        ) * COALESCE(
            (SELECT EXTRACT(EPOCH FROM (ended_at - started_at)) / 3600 FROM public.incidents WHERE id = v_incident_id),
            0
        ) + COALESCE(
            (SELECT SUM(downtime_rent_cost) FROM public.incident_affected_items WHERE incident_id = v_incident_id),
            0
        )
    )
    WHERE id = v_incident_id
      AND ended_at IS NOT NULL;

    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER","DROP TRIGGER IF EXISTS recalculate_incident_cost_after_items_change ON public.incident_affected_items","CREATE TRIGGER recalculate_incident_cost_after_items_change
    AFTER INSERT OR UPDATE OR DELETE ON public.incident_affected_items
    FOR EACH ROW
    EXECUTE FUNCTION public.recalculate_incident_cost_after_items_change()","NOTIFY pgrst, ''reload schema''"}', 'fix_incident_cost_recalc_trigger');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260628000003', '{"-- Migration: Remove downtime_rent_cost from cost_impact calculation
-- Downtime rent is compensated by the contracting company, so only time-based cost applies

CREATE OR REPLACE FUNCTION public.calculate_incident_cost_impact()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.ended_at IS NOT NULL THEN
        NEW.cost_impact := NEW.time_impact_hours * COALESCE(
            (SELECT SUM(hourly_cost_rate) FROM public.incident_affected_items WHERE incident_id = NEW.id),
            0
        );
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER","DROP TRIGGER IF EXISTS calculate_incident_cost_impact ON public.incidents","CREATE TRIGGER calculate_incident_cost_impact
    BEFORE INSERT OR UPDATE OF ended_at ON public.incidents
    FOR EACH ROW
    EXECUTE FUNCTION public.calculate_incident_cost_impact()"}', 'remove_rent_from_cost_impact');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260628000004', '{"-- Migration: Add day_type (working/non_working/partial) to daily reports
-- Enables marking a report as a rain day, half-day, etc.

-- 1. Add columns to daily_reports
ALTER TABLE public.daily_reports 
  ADD COLUMN IF NOT EXISTS day_type text NOT NULL DEFAULT ''working''
    CHECK (day_type IN (''working'', ''non_working'', ''partial''))","ALTER TABLE public.daily_reports 
  ADD COLUMN IF NOT EXISTS non_working_reason text","ALTER TABLE public.daily_reports
  ADD COLUMN IF NOT EXISTS stopped_at time","-- 2. Create project_non_working_days table (used by progress/SPI tracking)
CREATE TABLE IF NOT EXISTS public.project_non_working_days (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
    date date NOT NULL,
    reason text,
    partial_ratio numeric NOT NULL DEFAULT 0,  -- 0 = full non-working, 0.5 = half day, etc.
    daily_report_id uuid REFERENCES public.daily_reports(id) ON DELETE SET NULL,
    created_at timestamp with time zone DEFAULT now(),
    UNIQUE(project_id, date)
)","ALTER TABLE public.project_non_working_days ENABLE ROW LEVEL SECURITY","CREATE POLICY \"Allow all for authenticated users on project_non_working_days\"
  ON public.project_non_working_days FOR ALL TO authenticated USING (true)"}', 'add_day_type_to_daily_reports');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260703000000', '{"-- Migration: Weekly inspections & progress comparison
-- Adds drone/GPS inspection tracking, deviation detection, and reconciliation workflow

-- 1. Weekly inspections header
CREATE TABLE IF NOT EXISTS public.weekly_inspections (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
    inspection_date date NOT NULL,
    inspector_id uuid REFERENCES public.profiles(id),
    method text NOT NULL DEFAULT ''drone'' CHECK (method IN (''drone'', ''gps'', ''total_station'', ''other'')),
    general_notes text,
    evidence_files jsonb DEFAULT ''[]''::jsonb,
    status text NOT NULL DEFAULT ''draft'' CHECK (status IN (''draft'', ''submitted'', ''approved'', ''reconciled'')),
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    UNIQUE (project_id, inspection_date)
)","-- 2. Per-service measurements from each inspection
CREATE TABLE IF NOT EXISTS public.weekly_inspection_details (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    inspection_id uuid NOT NULL REFERENCES public.weekly_inspections(id) ON DELETE CASCADE,
    quote_service_id uuid NOT NULL REFERENCES public.quote_services(id) ON DELETE CASCADE,
    measured_quantity numeric NOT NULL DEFAULT 0,
    unit text,
    total_planned_quantity numeric NOT NULL DEFAULT 0,
    percentage_completion numeric NOT NULL DEFAULT 0,
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    UNIQUE (inspection_id, quote_service_id)
)","-- 3. Configurable thresholds per catalog service
CREATE TABLE IF NOT EXISTS public.service_inspection_thresholds (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    service_id uuid NOT NULL REFERENCES public.services(id) ON DELETE CASCADE,
    threshold_percentage numeric NOT NULL DEFAULT 5.0,
    active boolean NOT NULL DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    UNIQUE (service_id)
)","-- 4. Deviation comparison results
CREATE TABLE IF NOT EXISTS public.progress_comparisons (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    inspection_id uuid NOT NULL REFERENCES public.weekly_inspections(id) ON DELETE CASCADE,
    inspection_detail_id uuid NOT NULL REFERENCES public.weekly_inspection_details(id) ON DELETE CASCADE,
    quote_service_id uuid NOT NULL REFERENCES public.quote_services(id) ON DELETE CASCADE,
    period_start date,
    period_end date,
    accumulated_daily_quantity numeric NOT NULL DEFAULT 0,
    inspection_measured_quantity numeric NOT NULL DEFAULT 0,
    deviation_absolute numeric NOT NULL DEFAULT 0,
    deviation_percentage numeric NOT NULL DEFAULT 0,
    threshold_configured numeric NOT NULL DEFAULT 5.0,
    exceeds_threshold boolean NOT NULL DEFAULT false,
    status text NOT NULL DEFAULT ''pending''
        CHECK (status IN (''pending'', ''comparison_done'', ''exceeds_threshold'', ''pending_approval'', ''reconciled'')),
    reconciliation_notes text,
    proposed_by uuid REFERENCES public.profiles(id),
    proposed_at timestamp with time zone,
    approved_by uuid REFERENCES public.profiles(id),
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    UNIQUE (inspection_detail_id)
)","-- 5. Individual adjustments audit trail
CREATE TABLE IF NOT EXISTS public.progress_adjustments (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    comparison_id uuid NOT NULL REFERENCES public.progress_comparisons(id) ON DELETE CASCADE,
    daily_report_id uuid NOT NULL REFERENCES public.daily_reports(id) ON DELETE CASCADE,
    resource_type text NOT NULL CHECK (resource_type IN (''labor'', ''machinery'', ''material'')),
    log_id uuid NOT NULL,
    field_name text NOT NULL DEFAULT ''production_value'',
    original_value numeric NOT NULL DEFAULT 0,
    adjusted_value numeric NOT NULL DEFAULT 0,
    adjustment_reason text,
    adjusted_by uuid REFERENCES public.profiles(id),
    adjusted_at timestamp with time zone DEFAULT now()
)","-- Indexes
CREATE INDEX IF NOT EXISTS idx_weekly_inspections_project ON public.weekly_inspections(project_id, inspection_date)","CREATE INDEX IF NOT EXISTS idx_wi_details_inspection ON public.weekly_inspection_details(inspection_id)","CREATE INDEX IF NOT EXISTS idx_progress_comparisons_inspection ON public.progress_comparisons(inspection_id)","CREATE INDEX IF NOT EXISTS idx_progress_comparisons_status ON public.progress_comparisons(status)","CREATE INDEX IF NOT EXISTS idx_progress_comparisons_service ON public.progress_comparisons(quote_service_id)","CREATE INDEX IF NOT EXISTS idx_progress_adjustments_comparison ON public.progress_adjustments(comparison_id)","-- RLS Policies
ALTER TABLE public.weekly_inspections ENABLE ROW LEVEL SECURITY","CREATE POLICY \"Allow all for authenticated users on weekly_inspections\"
    ON public.weekly_inspections FOR ALL TO authenticated USING (true)","ALTER TABLE public.weekly_inspection_details ENABLE ROW LEVEL SECURITY","CREATE POLICY \"Allow all for authenticated users on weekly_inspection_details\"
    ON public.weekly_inspection_details FOR ALL TO authenticated USING (true)","ALTER TABLE public.service_inspection_thresholds ENABLE ROW LEVEL SECURITY","CREATE POLICY \"Allow all for authenticated users on service_inspection_thresholds\"
    ON public.service_inspection_thresholds FOR ALL TO authenticated USING (true)","ALTER TABLE public.progress_comparisons ENABLE ROW LEVEL SECURITY","CREATE POLICY \"Allow all for authenticated users on progress_comparisons\"
    ON public.progress_comparisons FOR ALL TO authenticated USING (true)","ALTER TABLE public.progress_adjustments ENABLE ROW LEVEL SECURITY","CREATE POLICY \"Allow all for authenticated users on progress_adjustments\"
    ON public.progress_adjustments FOR ALL TO authenticated USING (true)","-- Trigger: auto-calculate percentage completion on inspection detail insert
CREATE OR REPLACE FUNCTION public.calc_inspection_percentage()
RETURNS trigger AS $$
BEGIN
    IF NEW.total_planned_quantity > 0 THEN
        NEW.percentage_completion := ROUND((NEW.measured_quantity / NEW.total_planned_quantity) * 100, 2);
    ELSE
        NEW.percentage_completion := 0;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql","DROP TRIGGER IF EXISTS trg_calc_inspection_percentage ON public.weekly_inspection_details","CREATE TRIGGER trg_calc_inspection_percentage
    BEFORE INSERT OR UPDATE OF measured_quantity, total_planned_quantity
    ON public.weekly_inspection_details
    FOR EACH ROW EXECUTE FUNCTION public.calc_inspection_percentage()","-- Trigger: update updated_at on threshold changes
CREATE OR REPLACE FUNCTION public.update_inspection_updated_at()
RETURNS trigger AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql","DROP TRIGGER IF EXISTS trg_weekly_inspections_updated_at ON public.weekly_inspections","CREATE TRIGGER trg_weekly_inspections_updated_at
    BEFORE UPDATE ON public.weekly_inspections
    FOR EACH ROW EXECUTE FUNCTION public.update_inspection_updated_at()","DROP TRIGGER IF EXISTS trg_thresholds_updated_at ON public.service_inspection_thresholds","CREATE TRIGGER trg_thresholds_updated_at
    BEFORE UPDATE ON public.service_inspection_thresholds
    FOR EACH ROW EXECUTE FUNCTION public.update_inspection_updated_at()","DROP TRIGGER IF EXISTS trg_comparisons_updated_at ON public.progress_comparisons","CREATE TRIGGER trg_comparisons_updated_at
    BEFORE UPDATE ON public.progress_comparisons
    FOR EACH ROW EXECUTE FUNCTION public.update_inspection_updated_at()"}', 'add_weekly_inspections');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260709000000', '{"-- Migration: Add Machinery Rental Deductions for Billing
-- Allows deducting machinery rental costs from service line items in invoices

-- ============================================================
-- 1. INVOICE MACHINERY DEDUCTIONS TABLE
-- ============================================================
CREATE TABLE public.invoice_machinery_deductions (
  id                          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id                  uuid NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  quote_service_id            uuid NOT NULL REFERENCES public.quote_services(id) ON DELETE CASCADE,
  quote_service_machinery_id  uuid REFERENCES public.quote_service_machineries(id) ON DELETE SET NULL,
  machine_name                text NOT NULL,
  monthly_rent_cost           numeric NOT NULL DEFAULT 0,
  daily_rental_rate           numeric NOT NULL DEFAULT 0,
  days_in_period              numeric NOT NULL DEFAULT 0,
  deduction_amount            numeric NOT NULL DEFAULT 0,
  quantity                    numeric NOT NULL DEFAULT 1,
  selected                    boolean NOT NULL DEFAULT true,
  created_at                  timestamptz DEFAULT now(),
  UNIQUE(invoice_id, quote_service_id, quote_service_machinery_id)
)","-- ============================================================
-- 2. RPC: Get machinery for billing (by project)
-- ============================================================
CREATE OR REPLACE FUNCTION public.get_service_machinery_for_billing(p_project_id uuid)
RETURNS TABLE(
  quote_service_id uuid,
  quote_service_name text,
  quote_service_machinery_id uuid,
  machine_name text,
  monthly_rent_cost numeric,
  quantity numeric,
  daily_rental_rate numeric
) LANGUAGE sql STABLE AS $$
  SELECT
    qsm.quote_service_id,
    qs.name as quote_service_name,
    qsm.id as quote_service_machinery_id,
    qsm.machine_name,
    qsm.monthly_rent_cost,
    qsm.quantity,
    ROUND((qsm.monthly_rent_cost / 30.0)::numeric, 2) as daily_rental_rate
  FROM public.quote_service_machineries qsm
  JOIN public.quote_services qs ON qs.id = qsm.quote_service_id
  JOIN public.projects p ON p.quote_id = qs.quote_id
  WHERE p.id = p_project_id
    AND qsm.monthly_rent_cost > 0
  ORDER BY qs.name, qsm.machine_name;
$$","-- ============================================================
-- 3. ROW LEVEL SECURITY
-- ============================================================
ALTER TABLE public.invoice_machinery_deductions ENABLE ROW LEVEL SECURITY","CREATE POLICY select_invoice_machinery_deductions ON public.invoice_machinery_deductions
  FOR SELECT USING (true)","CREATE POLICY insert_invoice_machinery_deductions ON public.invoice_machinery_deductions
  FOR INSERT WITH CHECK (true)","CREATE POLICY update_invoice_machinery_deductions ON public.invoice_machinery_deductions
  FOR UPDATE USING (true)","CREATE POLICY delete_invoice_machinery_deductions ON public.invoice_machinery_deductions
  FOR DELETE USING (true)","NOTIFY pgrst, ''reload schema''"}', 'add_machinery_deductions');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260709000001', '{"-- Migration: Fix machinery deductions ÔÇö use individual inspections, not quote groups
-- Only show machines where ownership_type = ''rented'' and not returned

-- ============================================================
-- 1. DROP OLD TABLE AND RECREATE WITH CORRECT SCHEMA
-- ============================================================
DROP TABLE IF EXISTS public.invoice_machinery_deductions","CREATE TABLE public.invoice_machinery_deductions (
  id                          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id                  uuid NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  quote_service_id            uuid NOT NULL REFERENCES public.quote_services(id) ON DELETE CASCADE,
  machinery_inspection_id     uuid NOT NULL REFERENCES public.machinery_inspections(id) ON DELETE CASCADE,
  machine_name                text NOT NULL,
  internal_code               text,
  brand_model                 text,
  monthly_rent_cost           numeric NOT NULL DEFAULT 0,
  daily_rental_rate           numeric NOT NULL DEFAULT 0,
  days_in_period              numeric NOT NULL DEFAULT 0,
  deduction_amount            numeric NOT NULL DEFAULT 0,
  selected                    boolean NOT NULL DEFAULT true,
  created_at                  timestamptz DEFAULT now(),
  UNIQUE(invoice_id, quote_service_id, machinery_inspection_id)
)","-- ============================================================
-- 2. DROP OLD FUNCTION AND RECREATE
-- ============================================================
DROP FUNCTION IF EXISTS public.get_service_machinery_for_billing(uuid)","CREATE OR REPLACE FUNCTION public.get_service_machinery_for_billing(p_project_id uuid)
RETURNS TABLE(
  quote_service_id uuid,
  quote_service_name text,
  machinery_inspection_id uuid,
  machine_name text,
  internal_code text,
  brand_model text,
  monthly_rent_cost numeric,
  daily_rental_rate numeric
) LANGUAGE sql STABLE AS $$
  SELECT
    COALESCE(pm.quote_service_id, qsm.quote_service_id) as quote_service_id,
    qs.name as quote_service_name,
    mi.id as machinery_inspection_id,
    COALESCE(mi.internal_code, mi.internal_id, mi.brand_model, pm.machinery_name, ''Machine'') as machine_name,
    mi.internal_code,
    mi.brand_model,
    COALESCE(qsm.monthly_rent_cost, 0) as monthly_rent_cost,
    ROUND((COALESCE(qsm.monthly_rent_cost, 0) / 30.0)::numeric, 2) as daily_rental_rate
  FROM public.machinery_inspections mi
  JOIN public.project_machinery pm ON pm.id = mi.project_machinery_id
  LEFT JOIN public.quote_service_machineries qsm ON qsm.id = pm.quote_service_machinery_id
  LEFT JOIN public.quote_services qs ON qs.id = COALESCE(pm.quote_service_id, qsm.quote_service_id)
  WHERE pm.project_id = p_project_id
    AND mi.ownership_type = ''rented''
    AND mi.returned_at IS NULL
  ORDER BY qs.name, mi.internal_code, mi.brand_model;
$$","-- ============================================================
-- 3. ROW LEVEL SECURITY (re-create after drop)
-- ============================================================
ALTER TABLE public.invoice_machinery_deductions ENABLE ROW LEVEL SECURITY","CREATE POLICY select_invoice_machinery_deductions ON public.invoice_machinery_deductions
  FOR SELECT USING (true)","CREATE POLICY insert_invoice_machinery_deductions ON public.invoice_machinery_deductions
  FOR INSERT WITH CHECK (true)","CREATE POLICY update_invoice_machinery_deductions ON public.invoice_machinery_deductions
  FOR UPDATE USING (true)","CREATE POLICY delete_invoice_machinery_deductions ON public.invoice_machinery_deductions
  FOR DELETE USING (true)","NOTIFY pgrst, ''reload schema''"}', 'fix_machinery_deductions');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260804200000', '{"-- ============================================================
-- Migration: Separar servicios de CO de quote_services
-- Tabla project_services ÔÇö servicios al nivel del proyecto
-- quote_services = estimaci├│n baseline (read-only, nunca se modifica por COs)
-- project_services = versi├│n viva del proyecto (creada/modificada por COs)
-- ============================================================

-- 1. Crear tabla project_services
CREATE TABLE IF NOT EXISTS public.project_services (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id       uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,
  quote_service_id uuid REFERENCES public.quote_services(id) ON DELETE SET NULL,
  name             text NOT NULL,
  unit_of_measure  text NOT NULL DEFAULT ''und'',
  quantity         numeric NOT NULL DEFAULT 0,
  direct_cost      numeric NOT NULL DEFAULT 0,
  target_price     numeric DEFAULT 0,
  source_co_id     uuid REFERENCES public.change_orders(id) ON DELETE SET NULL,
  created_at       timestamptz DEFAULT now()
)","-- ├ìndices
CREATE INDEX IF NOT EXISTS idx_project_services_project ON public.project_services(project_id)","CREATE INDEX IF NOT EXISTS idx_project_services_quote ON public.project_services(quote_service_id)","CREATE INDEX IF NOT EXISTS idx_project_services_co ON public.project_services(source_co_id)","-- RLS
ALTER TABLE public.project_services ENABLE ROW LEVEL SECURITY","CREATE POLICY \"Authenticated full access\" ON public.project_services
  FOR ALL TO authenticated
  USING (true)
  WITH CHECK (true)","-- 2. Nueva columna project_service_id en tablas de recursos
ALTER TABLE public.project_labor
  ADD COLUMN IF NOT EXISTS project_service_id uuid REFERENCES public.project_services(id) ON DELETE SET NULL","ALTER TABLE public.project_machinery
  ADD COLUMN IF NOT EXISTS project_service_id uuid REFERENCES public.project_services(id) ON DELETE SET NULL","ALTER TABLE public.project_materials
  ADD COLUMN IF NOT EXISTS project_service_id uuid REFERENCES public.project_services(id) ON DELETE SET NULL","ALTER TABLE public.project_instruments
  ADD COLUMN IF NOT EXISTS project_service_id uuid REFERENCES public.project_services(id) ON DELETE SET NULL","ALTER TABLE public.project_tasks
  ADD COLUMN IF NOT EXISTS project_service_id uuid REFERENCES public.project_services(id) ON DELETE SET NULL","-- 3. Nueva columna en change_order_details
ALTER TABLE public.change_order_details
  ADD COLUMN IF NOT EXISTS project_service_id uuid
  REFERENCES public.project_services(id) ON DELETE SET NULL","CREATE INDEX IF NOT EXISTS idx_co_details_project_service ON public.change_order_details(project_service_id)"}', 'create_project_services');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260804000000', '{"-- Migration: Include owned machinery in billing deductions list
-- Previously only rented machinery was shown; now includes both rented and owned

CREATE OR REPLACE FUNCTION public.get_service_machinery_for_billing(p_project_id uuid)
RETURNS TABLE(
  quote_service_id uuid,
  quote_service_name text,
  machinery_inspection_id uuid,
  machine_name text,
  internal_code text,
  brand_model text,
  monthly_rent_cost numeric,
  daily_rental_rate numeric
) LANGUAGE sql STABLE AS $$
  SELECT
    COALESCE(pm.quote_service_id, qsm.quote_service_id) as quote_service_id,
    qs.name as quote_service_name,
    mi.id as machinery_inspection_id,
    COALESCE(mi.internal_code, mi.internal_id, mi.brand_model, pm.machinery_name, ''Machine'') as machine_name,
    mi.internal_code,
    mi.brand_model,
    COALESCE(qsm.monthly_rent_cost, (pm.calculation_metadata->>''monthly_rent'')::numeric, 0) as monthly_rent_cost,
    ROUND((COALESCE(qsm.monthly_rent_cost, (pm.calculation_metadata->>''monthly_rent'')::numeric, 0) / 30.0)::numeric, 2) as daily_rental_rate
  FROM public.machinery_inspections mi
  JOIN public.project_machinery pm ON pm.id = mi.project_machinery_id
  LEFT JOIN public.quote_service_machineries qsm ON qsm.id = pm.quote_service_machinery_id
  LEFT JOIN public.quote_services qs ON qs.id = COALESCE(pm.quote_service_id, qsm.quote_service_id)
  WHERE pm.project_id = p_project_id
    AND mi.returned_at IS NULL
  ORDER BY qs.name, mi.internal_code, mi.brand_model;
$$"}', 'include_owned_machinery_deductions');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260804200001', '{"-- ============================================================
-- Migration: Migrar datos CO existentes a project_services
-- 1. Copiar quote_services con source_co_id IS NOT NULL
-- 2. Poblar change_order_details.project_service_id para new_service
-- 3. Crear espejos project_services para existing_service con CO aprobado
-- ============================================================

-- 1. Copiar servicios CO nuevos (new_service) desde quote_services
INSERT INTO public.project_services
  (project_id, quote_service_id, name, unit_of_measure, quantity, direct_cost, target_price, source_co_id, created_at)
SELECT
  p.id,
  qs.id,
  qs.name,
  qs.unit_of_measure,
  qs.quantity,
  COALESCE(qs.direct_cost, 0),
  qs.target_price,
  qs.source_co_id,
  qs.created_at
FROM public.quote_services qs
JOIN public.quotes q ON q.id = qs.quote_id
JOIN public.projects p ON p.quote_id = q.id
WHERE qs.source_co_id IS NOT NULL","-- 2. Actualizar change_order_details: poblar project_service_id para line_type=''new_service''
UPDATE public.change_order_details cod
SET project_service_id = ps.id
FROM public.project_services ps
WHERE cod.quote_service_id = ps.quote_service_id
  AND cod.line_type = ''new_service''
  AND ps.quote_service_id IS NOT NULL","-- 3. Para existing_service con CO aprobado, crear espejos en project_services
--    con la cantidad ajustada (quote.quantity + suma de quantity_change de COs aprobados)
INSERT INTO public.project_services
  (project_id, quote_service_id, name, unit_of_measure, quantity, direct_cost, target_price, source_co_id, created_at)
SELECT DISTINCT ON (qs.id)
  co.project_id,
  qs.id,
  qs.name,
  qs.unit_of_measure,
  qs.quantity + COALESCE(
    (SELECT SUM(cod2.quantity_change)
     FROM public.change_order_details cod2
     JOIN public.change_orders co2 ON co2.id = cod2.change_order_id
     WHERE cod2.quote_service_id = qs.id
       AND co2.status = ''approved''
       AND cod2.line_type IN (''existing_service'', ''deduction'')),
    0
  ),
  COALESCE(qs.direct_cost, 0),
  qs.target_price,
  NULL,
  now()
FROM public.change_order_details cod
JOIN public.change_orders co ON co.id = cod.change_order_id
JOIN public.quote_services qs ON qs.id = cod.quote_service_id
JOIN public.quotes q ON q.id = qs.quote_id
JOIN public.projects p ON p.quote_id = q.id AND p.id = co.project_id
WHERE cod.line_type = ''existing_service''
  AND co.status = ''approved''
  AND qs.id NOT IN (
    SELECT quote_service_id FROM public.project_services WHERE quote_service_id IS NOT NULL
  )","-- 4. Poblar project_service_id en tablas de recursos para CO resources
--    donde el resource.quote_service_id coincide con el project_service.quote_service_id
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name = ''project_machinery'' AND column_name = ''project_service_id'') THEN
    UPDATE public.project_machinery pm
    SET project_service_id = ps.id
    FROM public.project_services ps
    WHERE pm.quote_service_id = ps.quote_service_id
      AND ps.quote_service_id IS NOT NULL
      AND pm.source_co_id IS NOT NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name = ''project_labor'' AND column_name = ''project_service_id'') THEN
    UPDATE public.project_labor pl
    SET project_service_id = ps.id
    FROM public.project_services ps
    WHERE pl.quote_service_id = ps.quote_service_id
      AND ps.quote_service_id IS NOT NULL
      AND pl.source_co_id IS NOT NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name = ''project_materials'' AND column_name = ''project_service_id'') THEN
    UPDATE public.project_materials pm2
    SET project_service_id = ps.id
    FROM public.project_services ps
    WHERE pm2.quote_service_id = ps.quote_service_id
      AND ps.quote_service_id IS NOT NULL
      AND pm2.source_co_id IS NOT NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name = ''project_instruments'' AND column_name = ''project_service_id'') THEN
    UPDATE public.project_instruments pi
    SET project_service_id = ps.id
    FROM public.project_services ps
    WHERE pi.quote_service_id = ps.quote_service_id
      AND ps.quote_service_id IS NOT NULL
      AND pi.source_co_id IS NOT NULL;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name = ''project_tasks'' AND column_name = ''project_service_id'') THEN
    UPDATE public.project_tasks pt
    SET project_service_id = ps.id
    FROM public.project_services ps
    WHERE pt.quote_service_id = ps.quote_service_id
      AND ps.quote_service_id IS NOT NULL
      AND pt.quote_service_id IS NOT NULL;
  END IF;
END
$$"}', 'migrate_co_services');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260804200002', '{"-- ============================================================
-- Migration: Actualizar trigger log_quote_service_changes
-- Ahora usa project_services en vez de modificar quote_services
-- quote_services = estimaci├│n baseline (nunca se modifica)
-- project_services = versi├│n viva del proyecto
-- ============================================================

CREATE OR REPLACE FUNCTION public.log_quote_service_changes()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_project_id          uuid;
  v_project_service_id  uuid;
  v_line                record;
  v_existing_qty        numeric;
BEGIN
  IF NEW.status = ''approved'' AND OLD.status = ''submitted'' THEN
    SELECT project_id INTO v_project_id FROM public.change_orders WHERE id = NEW.id;

    -- 1. existing_service / deduction: crear o actualizar project_service mirror
    FOR v_line IN
      SELECT
        cod.quote_service_id,
        cod.quantity_change,
        qs.name,
        qs.unit_of_measure,
        qs.quantity,
        COALESCE(qs.direct_cost, 0) as direct_cost,
        qs.target_price
      FROM public.change_order_details cod
      JOIN public.quote_services qs ON qs.id = cod.quote_service_id
      WHERE cod.change_order_id = NEW.id
        AND cod.line_type IN (''existing_service'', ''deduction'')
        AND cod.quote_service_id IS NOT NULL
        AND cod.quantity_change != 0
    LOOP
      -- Buscar project_service mirror existente
      SELECT id INTO v_project_service_id
      FROM public.project_services
      WHERE project_id = v_project_id
        AND quote_service_id = v_line.quote_service_id;

      IF v_project_service_id IS NULL THEN
        -- Crear mirror copiando del quote original
        INSERT INTO public.project_services
          (project_id, quote_service_id, name, unit_of_measure, quantity, direct_cost, target_price)
        VALUES
          (v_project_id, v_line.quote_service_id, v_line.name,
           COALESCE(v_line.unit_of_measure, ''und''), v_line.quantity,
           v_line.direct_cost, v_line.target_price)
        RETURNING id INTO v_project_service_id;
      END IF;

      -- Guardar cantidad anterior para el log
      SELECT quantity INTO v_existing_qty FROM public.project_services WHERE id = v_project_service_id;

      -- Actualizar project_service (NO quote_services)
      UPDATE public.project_services
      SET quantity = quantity + v_line.quantity_change
      WHERE id = v_project_service_id;

      -- Registrar cambio en log (referencia a quote_service original)
      INSERT INTO public.quote_service_change_log
        (quote_service_id, change_order_id, previous_quantity, new_quantity, delta_quantity)
      VALUES
        (v_line.quote_service_id, NEW.id, COALESCE(v_existing_qty, 0),
         COALESCE(v_existing_qty, 0) + v_line.quantity_change, v_line.quantity_change);
    END LOOP;

    -- 2. new_service: crear project_service directamente (sin tocar quote_services)
    FOR v_line IN
      SELECT
        cod.id as detail_id,
        cod.service_name,
        cod.unit_of_measure,
        cod.quantity_change,
        cod.unit_price
      FROM public.change_order_details cod
      WHERE cod.change_order_id = NEW.id
        AND cod.line_type = ''new_service''
        AND cod.quantity_change > 0
    LOOP
      INSERT INTO public.project_services
        (project_id, name, unit_of_measure, quantity, direct_cost, target_price, source_co_id)
      VALUES
        (v_project_id, v_line.service_name,
         COALESCE(v_line.unit_of_measure, ''und''), v_line.quantity_change,
         0, COALESCE(v_line.unit_price, 0), NEW.id)
      RETURNING id INTO v_project_service_id;

      -- Vincular change_order_details ÔåÆ project_services
      UPDATE public.change_order_details
      SET project_service_id = v_project_service_id
      WHERE id = v_line.detail_id;
    END LOOP;
  END IF;
  RETURN NULL;
END;
$$","-- Re-crear el trigger (misma definici├│n, nueva funci├│n)
DROP TRIGGER IF EXISTS trg_log_quote_service_changes ON public.change_orders","CREATE CONSTRAINT TRIGGER trg_log_quote_service_changes
  AFTER UPDATE ON public.change_orders
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW
  WHEN (NEW.status = ''approved'' AND OLD.status = ''submitted'')
  EXECUTE FUNCTION public.log_quote_service_changes()"}', 'update_trigger_project_services');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260804200003', '{"-- Migration: Update get_pay_application_data to include project_services
-- Adds pure new-service COs (project_services with quote_service_id IS NULL)
-- to the billing lines. Also includes project_services cost in contract total.

CREATE OR REPLACE FUNCTION public.get_pay_application_data(
  p_project_id    uuid,
  p_period_start  date,
  p_period_end    date,
  p_exclude_inv_id uuid DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE
  v_quote_id          uuid;
  v_original_contract numeric := 0;
  v_approved_cos      numeric := 0;
  v_previous_total    numeric := 0;
  v_lines             jsonb := ''[]''::jsonb;
  v_standby_lines     jsonb := ''[]''::jsonb;
  v_line              record;
  v_prev_rec          record;
  v_accumulated_qty   numeric;
  v_earned            numeric;
  v_this_period_amt   numeric;
  v_standby_rec       record;
  v_co_line           record;
  v_original_qty      numeric;
  v_original_sched    numeric;
  v_total_accum       numeric;
  v_remaining         numeric;
  v_segment_accum     numeric;
  v_ps_line           record;
BEGIN
  -- Get project quote_id
  SELECT quote_id INTO v_quote_id FROM public.projects WHERE id = p_project_id;

  -- Calculate original contract sum (quote_services + project_services)
  SELECT COALESCE(SUM(COALESCE(qs.direct_cost, 0)), 0) INTO v_original_contract
  FROM public.quote_services qs
  WHERE qs.quote_id = v_quote_id;

  v_original_contract := v_original_contract +
    COALESCE((SELECT SUM(COALESCE(ps.direct_cost, 0))
              FROM public.project_services ps
              WHERE ps.project_id = p_project_id), 0);

  -- Sum approved change orders
  SELECT COALESCE(SUM(adjustment_amount), 0) INTO v_approved_cos
  FROM public.change_orders
  WHERE project_id = p_project_id AND status = ''approved'';

  -- Sum previous billings (paid invoices)
  SELECT COALESCE(SUM(total_this_period), 0) INTO v_previous_total
  FROM public.invoices
  WHERE project_id = p_project_id AND status = ''paid'';

  -- Build invoice lines from quote_services
  FOR v_line IN
    SELECT
      qs.id as quote_service_id,
      qs.name as service_name,
      qs.unit_of_measure,
      COALESCE(qs.direct_cost, 0) as scheduled_value,
      qs.quantity as contract_quantity
    FROM public.quote_services qs
    WHERE qs.quote_id = v_quote_id
    ORDER BY qs.created_at
  LOOP
    -- Calculate total accumulated production for this service
    SELECT COALESCE(SUM(
      CASE WHEN LOWER(v_line.unit_of_measure) IN (''cy'', ''ft2'', ''sqft'', ''sf'')
           THEN rml.production_value * COALESCE(m.capacity_yards, 1)
           ELSE rml.production_value
      END
    ), 0)
    INTO v_accumulated_qty
    FROM public.report_machinery_logs rml
    JOIN public.daily_reports dr ON dr.id = rml.daily_report_id
    JOIN public.project_machinery pm ON pm.id = rml.project_machinery_id
    LEFT JOIN public.machinery m ON m.id = pm.machinery_id
    WHERE pm.quote_service_id = v_line.quote_service_id
      AND dr.project_id = p_project_id
      AND dr.report_date <= p_period_end
      AND dr.status IN (''submitted'', ''approved'')
      AND rml.is_standby = false;

    -- Check for approved existing_service CO details linked to this service
    IF EXISTS (
      SELECT 1 FROM public.change_order_details cod
      JOIN public.change_orders co ON co.id = cod.change_order_id
      WHERE cod.quote_service_id = v_line.quote_service_id
        AND co.project_id = p_project_id
        AND co.status = ''approved''
        AND cod.line_type = ''existing_service''
    ) THEN
      -- Segmentation mode: split into original scope + CO increments (FIFO)
      v_total_accum := v_accumulated_qty;
      v_remaining := v_total_accum;

      -- 1. Original scope line
      SELECT v_line.contract_quantity - COALESCE(SUM(cod.quantity_change), 0)
        INTO v_original_qty
      FROM public.change_order_details cod
      JOIN public.change_orders co ON co.id = cod.change_order_id
      WHERE cod.quote_service_id = v_line.quote_service_id
        AND co.project_id = p_project_id
        AND co.status = ''approved''
        AND cod.line_type IN (''existing_service'', ''deduction'');

      IF v_original_qty < 0 THEN
        v_original_qty := 0;
      END IF;

      IF v_line.contract_quantity > 0 THEN
        v_original_sched := ROUND((v_original_qty / v_line.contract_quantity) * v_line.scheduled_value, 2);
      ELSE
        v_original_sched := v_line.scheduled_value;
      END IF;

      v_segment_accum := LEAST(v_remaining, v_original_qty);

      SELECT total_previous, total_previous_qty
      INTO v_prev_rec
      FROM public.get_previous_billing_totals(p_project_id, p_exclude_inv_id)
      WHERE quote_service_id = v_line.quote_service_id;

      v_this_period_amt := 0;
      IF v_original_qty > 0 AND v_original_sched > 0 THEN
        v_earned := (v_segment_accum / v_original_qty) * v_original_sched;
        v_this_period_amt := GREATEST(0, v_earned - COALESCE(v_prev_rec.total_previous, 0));
      END IF;

      v_lines := v_lines || jsonb_build_object(
        ''quote_service_id'', v_line.quote_service_id,
        ''service_name'', v_line.service_name || '' (Original)'',
        ''unit_of_measure'', v_line.unit_of_measure,
        ''line_type'', ''service'',
        ''co_segment'', ''original'',
        ''scheduled_value'', v_original_sched,
        ''contract_quantity'', v_original_qty,
        ''previous_completed'', COALESCE(v_prev_rec.total_previous, 0),
        ''previous_qty'', COALESCE(v_prev_rec.total_previous_qty, 0),
        ''this_period_qty'', v_segment_accum,
        ''this_period_amount'', v_this_period_amt,
        ''equipment_present'', 0
      );

      v_remaining := GREATEST(0, v_remaining - v_original_qty);

      -- 2. CO increment lines (one per approved existing_service detail, in approval order)
      FOR v_co_line IN
        SELECT
          cod.id as detail_id,
          cod.service_name,
          cod.unit_of_measure,
          COALESCE(cod.total_change, 0) as total_change,
          COALESCE(cod.quantity_change, 0) as quantity_change,
          COALESCE(cod.unit_price, 0) as unit_price,
          co.co_number,
          co.id as co_id,
          co.approved_at
        FROM public.change_order_details cod
        JOIN public.change_orders co ON co.id = cod.change_order_id
        WHERE cod.quote_service_id = v_line.quote_service_id
          AND co.project_id = p_project_id
          AND co.status = ''approved''
          AND cod.line_type = ''existing_service''
          AND cod.quantity_change > 0
        ORDER BY COALESCE(cod.effective_date, co.approved_at::date) ASC
      LOOP
        v_segment_accum := LEAST(v_remaining, v_co_line.quantity_change);

        v_this_period_amt := 0;
        IF v_co_line.quantity_change > 0 AND v_co_line.total_change > 0 THEN
          v_earned := (v_segment_accum / v_co_line.quantity_change) * v_co_line.total_change;
          v_this_period_amt := v_earned;
        END IF;

        v_lines := v_lines || jsonb_build_object(
          ''quote_service_id'', v_line.quote_service_id,
          ''co_detail_id'', v_co_line.detail_id,
          ''service_name'', ''CO: '' || v_line.service_name || '' (+'' || v_co_line.quantity_change::text || '' '' || v_co_line.unit_of_measure || '' ├ù $'' || ROUND(v_co_line.unit_price, 2)::text || '') '' || v_co_line.co_number,
          ''unit_of_measure'', v_co_line.unit_of_measure,
          ''line_type'', ''change_order_detail'',
          ''co_segment'', ''increment'',
          ''co_id'', v_co_line.co_id,
          ''co_number'', v_co_line.co_number,
          ''scheduled_value'', v_co_line.total_change,
          ''contract_quantity'', v_co_line.quantity_change,
          ''previous_completed'', 0,
          ''previous_qty'', 0,
          ''this_period_qty'', v_segment_accum,
          ''this_period_amount'', v_this_period_amt,
          ''equipment_present'', 0
        );

        v_remaining := GREATEST(0, v_remaining - v_co_line.quantity_change);
      END LOOP;

    ELSE
      -- Standard mode: no existing_service COs ÔåÆ single line
      SELECT total_previous, total_previous_qty
      INTO v_prev_rec
      FROM public.get_previous_billing_totals(p_project_id, p_exclude_inv_id)
      WHERE quote_service_id = v_line.quote_service_id;

      v_this_period_amt := 0;
      IF v_line.contract_quantity > 0 AND v_line.scheduled_value > 0 THEN
        v_earned := (v_accumulated_qty / v_line.contract_quantity) * v_line.scheduled_value;
        v_this_period_amt := GREATEST(0, v_earned - COALESCE(v_prev_rec.total_previous, 0));
      END IF;

      v_lines := v_lines || jsonb_build_object(
        ''quote_service_id'', v_line.quote_service_id,
        ''service_name'', v_line.service_name,
        ''unit_of_measure'', v_line.unit_of_measure,
        ''line_type'', ''service'',
        ''co_segment'', ''none'',
        ''scheduled_value'', v_line.scheduled_value,
        ''contract_quantity'', v_line.contract_quantity,
        ''previous_completed'', COALESCE(v_prev_rec.total_previous, 0),
        ''previous_qty'', COALESCE(v_prev_rec.total_previous_qty, 0),
        ''this_period_qty'', v_accumulated_qty,
        ''this_period_amount'', v_this_period_amt,
        ''equipment_present'', 0
      );
    END IF;
  END LOOP;

  -- 3. Add project_services (pure new-service COs, no quote_service_id)
  FOR v_ps_line IN
    SELECT
      ps.id as project_service_id,
      ps.name as service_name,
      ps.unit_of_measure,
      COALESCE(ps.target_price, 0) as scheduled_value,
      ps.quantity as contract_quantity,
      COALESCE(ps.direct_cost, 0) as direct_cost
    FROM public.project_services ps
    WHERE ps.project_id = p_project_id
      AND ps.quote_service_id IS NULL
    ORDER BY ps.created_at
  LOOP
    -- Calculate accumulated production via project_service_id
    SELECT COALESCE(SUM(
      CASE WHEN LOWER(v_ps_line.unit_of_measure) IN (''cy'', ''ft2'', ''sqft'', ''sf'')
           THEN rml.production_value * COALESCE(m.capacity_yards, 1)
           ELSE rml.production_value
      END
    ), 0)
    INTO v_accumulated_qty
    FROM public.report_machinery_logs rml
    JOIN public.daily_reports dr ON dr.id = rml.daily_report_id
    JOIN public.project_machinery pm ON pm.id = rml.project_machinery_id
    LEFT JOIN public.machinery m ON m.id = pm.machinery_id
    WHERE pm.project_service_id = v_ps_line.project_service_id
      AND dr.project_id = p_project_id
      AND dr.report_date <= p_period_end
      AND dr.status IN (''submitted'', ''approved'')
      AND rml.is_standby = false;

    v_this_period_amt := 0;
    IF v_ps_line.contract_quantity > 0 AND v_ps_line.scheduled_value > 0 THEN
      v_earned := (v_accumulated_qty / v_ps_line.contract_quantity) * v_ps_line.scheduled_value;
      v_this_period_amt := v_earned;
    END IF;

    IF v_ps_line.direct_cost > 0 AND v_ps_line.scheduled_value = 0 THEN
      v_this_period_amt := (v_accumulated_qty / v_ps_line.contract_quantity) * v_ps_line.direct_cost;
    END IF;

    v_lines := v_lines || jsonb_build_object(
      ''quote_service_id'', null,
      ''project_service_id'', v_ps_line.project_service_id,
      ''service_name'', v_ps_line.service_name || '' (CO)'',
      ''unit_of_measure'', v_ps_line.unit_of_measure,
      ''line_type'', ''service'',
      ''co_segment'', ''none'',
      ''scheduled_value'', GREATEST(v_ps_line.scheduled_value, v_ps_line.direct_cost),
      ''contract_quantity'', v_ps_line.contract_quantity,
      ''previous_completed'', 0,
      ''previous_qty'', 0,
      ''this_period_qty'', v_accumulated_qty,
      ''this_period_amount'', v_this_period_amt,
      ''equipment_present'', 0
    );
  END LOOP;

  -- Accumulated standby hours from machinery logs (by CO detail)
  FOR v_standby_rec IN
    SELECT
      cod.id as co_detail_id,
      cod.service_name,
      cod.unit_of_measure,
      COALESCE(cod.standby_hours, 0) as estimated_hours,
      COALESCE(cod.standby_rate, 0) as standby_rate,
      cod.line_type,
      co.co_number,
      co.id as co_id,
      SUM(COALESCE(rml.standby_hours, 0)) as actual_hours,
      SUM(COALESCE(rml.standby_hours, 0) * COALESCE(cod.standby_rate, 0)) as calculated_amount
    FROM public.change_order_details cod
    JOIN public.change_orders co ON co.id = cod.change_order_id
    LEFT JOIN public.report_machinery_logs rml
      ON rml.change_order_detail_id = cod.id
      AND rml.is_standby = true
    LEFT JOIN public.daily_reports dr ON dr.id = rml.daily_report_id
      AND dr.project_id = p_project_id
      AND dr.report_date BETWEEN p_period_start AND p_period_end
      AND dr.status IN (''submitted'', ''approved'')
    WHERE co.project_id = p_project_id
      AND co.status = ''approved''
      AND cod.line_type = ''standby_machinery''
    GROUP BY cod.id, cod.service_name, cod.unit_of_measure, cod.standby_hours,
             cod.standby_rate, cod.line_type, co.co_number, co.id
    HAVING SUM(COALESCE(rml.standby_hours, 0)) > 0
  LOOP
    v_standby_lines := v_standby_lines || jsonb_build_object(
      ''co_id'', v_standby_rec.co_id,
      ''co_detail_id'', v_standby_rec.co_detail_id,
      ''co_number'', v_standby_rec.co_number,
      ''service_name'', ''Standby: '' || v_standby_rec.service_name || '' ('' || v_standby_rec.co_number || '')'',
      ''unit_of_measure'', ''hrs'',
      ''line_type'', ''standby_machinery'',
      ''estimated_hours'', v_standby_rec.estimated_hours,
      ''actual_hours'', v_standby_rec.actual_hours,
      ''standby_rate'', v_standby_rec.standby_rate,
      ''this_period_amount'', v_standby_rec.calculated_amount,
      ''scheduled_value'', v_standby_rec.estimated_hours * v_standby_rec.standby_rate
    );
  END LOOP;

  -- Accumulated standby hours from labor logs (by CO detail)
  FOR v_standby_rec IN
    SELECT
      cod.id as co_detail_id,
      cod.service_name,
      cod.unit_of_measure,
      COALESCE(cod.standby_hours, 0) as estimated_hours,
      COALESCE(cod.standby_rate, 0) as standby_rate,
      cod.line_type,
      co.co_number,
      co.id as co_id,
      SUM(COALESCE(rll.standby_hours, 0)) as actual_hours,
      SUM(COALESCE(rll.standby_hours, 0) * COALESCE(cod.standby_rate, 0)) as calculated_amount
    FROM public.change_order_details cod
    JOIN public.change_orders co ON co.id = cod.change_order_id
    LEFT JOIN public.report_labor_logs rll
      ON rll.change_order_detail_id = cod.id
      AND rll.is_standby = true
    LEFT JOIN public.daily_reports dr ON dr.id = rll.daily_report_id
      AND dr.project_id = p_project_id
      AND dr.report_date BETWEEN p_period_start AND p_period_end
      AND dr.status IN (''submitted'', ''approved'')
    WHERE co.project_id = p_project_id
      AND co.status = ''approved''
      AND cod.line_type = ''standby_labor''
    GROUP BY cod.id, cod.service_name, cod.unit_of_measure, cod.standby_hours,
             cod.standby_rate, cod.line_type, co.co_number, co.id
    HAVING SUM(COALESCE(rll.standby_hours, 0)) > 0
  LOOP
    v_standby_lines := v_standby_lines || jsonb_build_object(
      ''co_id'', v_standby_rec.co_id,
      ''co_detail_id'', v_standby_rec.co_detail_id,
      ''co_number'', v_standby_rec.co_number,
      ''service_name'', ''Standby Labor: '' || v_standby_rec.service_name || '' ('' || v_standby_rec.co_number || '')'',
      ''unit_of_measure'', ''hrs'',
      ''line_type'', ''standby_labor'',
      ''estimated_hours'', v_standby_rec.estimated_hours,
      ''actual_hours'', v_standby_rec.actual_hours,
      ''standby_rate'', v_standby_rec.standby_rate,
      ''this_period_amount'', v_standby_rec.calculated_amount,
      ''scheduled_value'', v_standby_rec.estimated_hours * v_standby_rec.standby_rate
    );
  END LOOP;

  -- Accumulated material waste (by CO detail)
  FOR v_standby_rec IN
    SELECT
      cod.id as co_detail_id,
      cod.service_name,
      cod.unit_of_measure,
      COALESCE(cod.quantity_lost, 0) as estimated_lost,
      COALESCE(cod.replacement_unit_cost, 0) as replacement_cost,
      cod.line_type,
      co.co_number,
      co.id as co_id,
      SUM(COALESCE(rmu.quantity_used, 0)) as actual_lost,
      SUM(COALESCE(rmu.replacement_cost, 0)) as actual_replacement_cost
    FROM public.change_order_details cod
    JOIN public.change_orders co ON co.id = cod.change_order_id
    LEFT JOIN public.report_material_usage rmu
      ON rmu.change_order_detail_id = cod.id
      AND rmu.is_waste = true
    LEFT JOIN public.daily_reports dr ON dr.id = rmu.daily_report_id
      AND dr.project_id = p_project_id
      AND dr.report_date BETWEEN p_period_start AND p_period_end
      AND dr.status IN (''submitted'', ''approved'')
    WHERE co.project_id = p_project_id
      AND co.status = ''approved''
      AND cod.line_type = ''standby_material''
    GROUP BY cod.id, cod.service_name, cod.unit_of_measure, cod.quantity_lost,
             cod.replacement_unit_cost, cod.line_type, co.co_number, co.id
    HAVING SUM(COALESCE(rmu.quantity_used, 0)) > 0
  LOOP
    v_standby_lines := v_standby_lines || jsonb_build_object(
      ''co_id'', v_standby_rec.co_id,
      ''co_detail_id'', v_standby_rec.co_detail_id,
      ''co_number'', v_standby_rec.co_number,
      ''service_name'', ''Material Lost: '' || v_standby_rec.service_name || '' ('' || v_standby_rec.co_number || '')'',
      ''unit_of_measure'', v_standby_rec.unit_of_measure,
      ''line_type'', ''standby_material'',
      ''estimated_lost'', v_standby_rec.estimated_lost,
      ''actual_lost'', v_standby_rec.actual_lost,
      ''replacement_cost'', v_standby_rec.replacement_cost,
      ''actual_replacement_cost'', v_standby_rec.actual_replacement_cost,
      ''this_period_amount'', COALESCE(v_standby_rec.actual_replacement_cost, 0),
      ''scheduled_value'', v_standby_rec.estimated_lost * v_standby_rec.replacement_cost
    );
  END LOOP;

  RETURN jsonb_build_object(
    ''original_contract'', v_original_contract,
    ''approved_cos_total'', v_approved_cos,
    ''current_contract'', v_original_contract + v_approved_cos,
    ''previous_total'', v_previous_total,
    ''lines'', v_lines,
    ''standby_lines'', v_standby_lines
  );
END;
$$"}', 'update_billing_rpc');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260805000000', '{"-- Split project_labor rows where expected_employees > 1 into individual rows
-- Each row now represents exactly 1 worker slot (expected_employees = 1)
-- Mirrors machinery split in 20260723000000_split_project_machinery_quantity.sql

DO $$
DECLARE
    rec RECORD;
    i INT;
BEGIN
    FOR rec IN
        SELECT * FROM public.project_labor WHERE expected_employees > 1
    LOOP
        FOR i IN 1..(rec.expected_employees - 1) LOOP
            INSERT INTO public.project_labor (
                project_id, quote_service_labor_id, quote_service_id,
                role_name, expected_employees, active_employees,
                is_unplanned, linked_machinery_id, unplanned_cost,
                calculation_metadata, role_id, start_date, end_date,
                change_type, baseline_snapshot_id, source_co_id,
                project_service_id
            ) VALUES (
                rec.project_id, rec.quote_service_labor_id, rec.quote_service_id,
                rec.role_name, 1, 0,
                rec.is_unplanned, rec.linked_machinery_id, rec.unplanned_cost,
                rec.calculation_metadata, rec.role_id, rec.start_date, rec.end_date,
                rec.change_type, rec.baseline_snapshot_id, rec.source_co_id,
                rec.project_service_id
            );
        END LOOP;

        UPDATE public.project_labor
        SET expected_employees = 1,
            active_employees = CASE WHEN active_employees > 1 THEN 1 ELSE active_employees END
        WHERE id = rec.id;
    END LOOP;
END;
$$"}', 'split_project_labor');
INSERT INTO supabase_migrations.schema_migrations (version, statements, name) VALUES ('20260805000001', '{"-- Redistribute project_labor_assignments across sibling project_labor rows
-- After the labor split, all assignments pile on one row. Siblings are empty.
-- This moves one assignment from the \"rich\" row to each empty sibling.

DO $$
DECLARE
    empty_rec RECORD;
    rich_rec RECORD;
BEGIN
    FOR empty_rec IN
        SELECT pl.id, pl.project_id, pl.quote_service_id, pl.role_name
        FROM public.project_labor pl
        WHERE NOT EXISTS (
            SELECT 1 FROM public.project_labor_assignments pla
            WHERE pla.project_labor_id = pl.id
        )
    LOOP
        SELECT a.id as assignment_id
        INTO rich_rec
        FROM public.project_labor pl2
        JOIN public.project_labor_assignments a ON a.project_labor_id = pl2.id
        WHERE pl2.project_id = empty_rec.project_id
          AND pl2.quote_service_id IS NOT DISTINCT FROM empty_rec.quote_service_id
          AND pl2.role_name = empty_rec.role_name
          AND pl2.id != empty_rec.id
        LIMIT 1;

        IF FOUND THEN
            UPDATE public.project_labor_assignments
            SET project_labor_id = empty_rec.id
            WHERE id = rich_rec.assignment_id;
        END IF;
    END LOOP;
END;
$$"}', 'redistribute_labor_assignments');


